INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('yue-chunqiu','越','["越","越国"]',NULL,'cn','east_asia',-565,1,NULL,'year',-306,12,NULL,'month',-6768,-3649,'ochre',NULL,NULL,'东南古国。传说夏少康庶子无余始封会稽，中间世系多缺载；有年表自允常。勾践灭吴后北进；前306年楚破越。');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fan-li','范蠡','yue-chunqiu','[]',NULL,NULL,-536,1,NULL,'year',-448,1,NULL,'year','["政治家","军事家"]','春秋末楚国人，字少伯，仕越为大夫，与文种辅佐越王勾践复国灭吴。越国称霸后辞官离去，辗转齐、陶经商致富，后世尊称陶朱公；晚年事迹多带传说色彩。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/范蠡"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gou-jian','勾践','yue-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','先败于夫差，屈身臣吴后反击灭吴，称霸东南。「卧薪尝胆」典出其事，越国霸业巅峰，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/勾践"}]',NULL,NULL,'勾践','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yue-r10','错枝','yue-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','在位仅两年，为弟所弑。越国内乱频仍，国势继续衰落，无力维持霸主地位，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/错枝"}]',NULL,NULL,'错枝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yue-r11','无余','yue-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','在位十一年，越国继续衰落，无力维持霸主地位，诸侯纷纷自立，国势转弱，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/无余"}]',NULL,NULL,'无余','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yue-r12','无颛','yue-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','在位近二十年，越国内乱不止，诸侯纷纷自立，国势奄奄一息，濒临分裂，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/无颛"}]',NULL,NULL,'无颛','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yue-r13','无彊','yue-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','越国末代君主，无彊。扩张过度，遭楚、齐攻杀，越国分裂，霸业终结，国亡，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/无彊"}]',NULL,NULL,'无彊','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yue-r3','夫谭','yue-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','越国早期君主，允常之父，名夫谭。传世资料主要保存其世次，具体经历及在位起讫缺乏可靠记载，不能据后来的吴越争霸推定其时国势。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/夫谭"}]',NULL,NULL,'夫谭','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yue-r4','允常','yue-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','允常，勾践之父。在位时越国与吴国时有争战，国势渐起，为勾践霸业奠基，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/允常"}]',NULL,NULL,'允常','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yue-r6','与夷','yue-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','鹿郢又名与夷、于赐，是越王勾践之子。勾践灭吴后由鹿郢继位，越国继续维持对吴胜利后的区域优势；其后由不寿继承。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鹿郢"}]',NULL,NULL,'鹿郢','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yue-r7','不寿','yue-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','勾践之子，不寿。在位时吴国已亡，越国内部渐有纷争，国势转衰，无力维持霸业，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/不寿"}]',NULL,NULL,'不寿','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yue-r8','翁','yue-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','越王朱勾，名翁，一作州勾，不寿之子。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱勾"}]',NULL,NULL,'朱勾','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yue-r9','翳','yue-chunqiu','[]','姒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','迁都琅邪，分封诸子于各地。越国由盛转衰，内乱加剧，诸侯离心，霸业渐失，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/翳"}]',NULL,NULL,'翳','[]');
